import java.util.*;
public class Phase9Harness{static int p=0;static List<String> f=new ArrayList<>();enum Auth{SIGNED_OUT,SIGNED_IN}record Backup(boolean encrypted,int rows){}static boolean canSync(Auth a){return a==Auth.SIGNED_IN;}static String conflict(String local,String remote){return local.compareTo(remote)>=0?local:remote;}static boolean validBackup(Backup b){return b.encrypted&&b.rows>=0;}static void eq(String n,Object e,Object a){if(Objects.equals(e,a))p++;else f.add(n+" expected "+e+" got "+a);}public static void main(String[]a){eq("signed out no sync",false,canSync(Auth.SIGNED_OUT));eq("signed in sync",true,canSync(Auth.SIGNED_IN));eq("latest wins local","2026-09-13T10",conflict("2026-09-13T10","2026-09-13T09"));eq("latest wins remote","2026-09-13T11",conflict("2026-09-13T10","2026-09-13T11"));eq("backup valid",true,validBackup(new Backup(true,5)));eq("backup must encrypt",false,validBackup(new Backup(false,5)));System.out.println("PASSED: "+p+" assertions");if(!f.isEmpty()){f.forEach(System.out::println);System.exit(1);}System.out.println("ALL PHASE 9 CHECKS PASSED");}}
